-- Statute library: every section of the BNS, BNSS, BSA and IPC, the special Acts
-- most cited in Kolkata FIRs, and the official IPC -> BNS correspondence.
--
-- This is law text used as reference data, not records. Each Act row names its
-- source and retrieval date. Rows shipped here are built-in: a trigger refuses
-- to change or delete them, so a correction to the law arrives as a new
-- migration, and officers add further Acts or sections as custom rows (audited
-- through the API) without touching the published text.

CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE IF NOT EXISTS legal_acts (
    id              UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    code            VARCHAR(16)  NOT NULL UNIQUE CHECK (code ~ '^[A-Z0-9_]{2,16}$'),
    citation        VARCHAR(40)  NOT NULL,
    short_name      VARCHAR(120) NOT NULL,
    name            VARCHAR(255) NOT NULL,
    year            INTEGER      CHECK (year BETWEEN 1800 AND 2100),
    act_number      VARCHAR(40),
    in_force_from   DATE,
    repealed_from   DATE,
    source          TEXT         NOT NULL,
    source_url      TEXT,
    retrieved_on    DATE,
    completeness    VARCHAR(12)  NOT NULL CHECK (completeness IN ('complete', 'selected')),
    status          VARCHAR(10)  NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'retired')),
    is_builtin      BOOLEAN      NOT NULL DEFAULT false,
    retired_reason  TEXT,
    created_by      UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    CONSTRAINT legal_act_retired_has_reason CHECK (status = 'active' OR retired_reason IS NOT NULL),
    CONSTRAINT legal_act_builtin_active CHECK (NOT is_builtin OR status = 'active')
);

CREATE TABLE IF NOT EXISTS legal_sections (
    id              UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    act_id          UUID NOT NULL REFERENCES legal_acts(id),
    number          VARCHAR(24)  NOT NULL CHECK (number ~ '^[0-9]{1,4}(-?[A-Z]{1,4})?(\([0-9A-Za-z]+\))*$'),
    sort_order      INTEGER      NOT NULL DEFAULT 100000,
    heading         TEXT         NOT NULL CHECK (length(trim(heading)) > 0),
    description     TEXT,
    -- Rows of the First Schedule (Part I) of the BNSS for a BNS offence, one per
    -- sub-section: [{ref, offence, punishment, cognizable, bailable, triableBy}].
    -- NULL where the source gives no classification.
    classification  JSONB CHECK (classification IS NULL OR jsonb_typeof(classification) = 'array'),
    status          VARCHAR(10)  NOT NULL DEFAULT 'in_force' CHECK (status IN ('in_force', 'repealed', 'retired')),
    is_builtin      BOOLEAN      NOT NULL DEFAULT false,
    retired_reason  TEXT,
    created_by      UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    CONSTRAINT legal_section_unique UNIQUE (act_id, number),
    CONSTRAINT legal_section_retired_has_reason CHECK (status <> 'retired' OR retired_reason IS NOT NULL),
    CONSTRAINT legal_section_builtin_not_retired CHECK (NOT is_builtin OR status <> 'retired')
);
CREATE INDEX IF NOT EXISTS idx_legal_sections_act_order ON legal_sections (act_id, sort_order);
CREATE INDEX IF NOT EXISTS idx_legal_sections_heading_trgm ON legal_sections USING gin (heading gin_trgm_ops);

-- One row per BNS provision in the BPR&D correspondence table.
CREATE TABLE IF NOT EXISTS legal_correspondence (
    id              UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    bns_ref         VARCHAR(40)  NOT NULL,
    bns_section     VARCHAR(12)  NOT NULL,
    ipc_ref         TEXT         NOT NULL DEFAULT '',
    ipc_sections    TEXT[]       NOT NULL DEFAULT '{}',
    subject         TEXT         NOT NULL DEFAULT '',
    source          TEXT         NOT NULL,
    CONSTRAINT legal_correspondence_unique UNIQUE (bns_ref, ipc_ref)
);
CREATE INDEX IF NOT EXISTS idx_legal_corr_bns ON legal_correspondence (bns_section);
CREATE INDEX IF NOT EXISTS idx_legal_corr_ipc ON legal_correspondence USING gin (ipc_sections);

-- Published law text is not editable through the application.
CREATE OR REPLACE FUNCTION legal_builtin_readonly() RETURNS trigger AS $$
BEGIN
    IF OLD.is_builtin THEN
        RAISE EXCEPTION 'built-in statute rows are read-only (%)', TG_TABLE_NAME
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    IF NEW.is_builtin THEN
        RAISE EXCEPTION 'a custom row cannot be marked built-in' USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS legal_acts_builtin_readonly ON legal_acts;
CREATE TRIGGER legal_acts_builtin_readonly BEFORE UPDATE OR DELETE ON legal_acts
    FOR EACH ROW EXECUTE FUNCTION legal_builtin_readonly();
DROP TRIGGER IF EXISTS legal_sections_builtin_readonly ON legal_sections;
CREATE TRIGGER legal_sections_builtin_readonly BEFORE UPDATE OR DELETE ON legal_sections
    FOR EACH ROW EXECUTE FUNCTION legal_builtin_readonly();
DROP TRIGGER IF EXISTS legal_correspondence_readonly ON legal_correspondence;
CREATE OR REPLACE FUNCTION legal_correspondence_readonly() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'the correspondence table is published reference data and is read-only'
        USING ERRCODE = 'integrity_constraint_violation';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER legal_correspondence_readonly BEFORE UPDATE OR DELETE ON legal_correspondence
    FOR EACH ROW EXECUTE FUNCTION legal_correspondence_readonly();


