('65', 65, 'Punishment for rape in certain cases.', 'in_force', '[{"ref": "65(1)", "offence": "Persons committing offence of rape on a woman under sixteen years of age.", "punishment": "Rigorous imprisonment for not less than 20 years but which may extend to imprisonment for life, which shall mean imprisonment for the remainder of that person''s natural life and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "65(2)", "offence": "Persons committing offence of rape on a woman under twelve years of age.", "punishment": "Rigorous imprisonment for not less than 20 years but which may extend to imprisonment for life which shall mean imprisonment for the remainder of that person''s natural life and with fine or death.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
