('68', 68, 'Sexual intercourse by a person in authority.', 'in_force', '[{"ref": "68", "offence": "Sexual intercourse by a person in authority, etc.", "punishment": "Rigorous imprisonment for not less than 5 years, but which may extend to 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('69', 69, 'Sexual intercourse by employing deceitful means, etc.', 'in_force', '[{"ref": "69", "offence": "Sexual intercourse by employing deceitful means, etc.", "punishment": "Imprisonment which may extend to 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('70', 70, 'Gang rape.', 'in_force', '[{"ref": "70(1)", "offence": "Gang rape.", "punishment": "Rigorous imprisonment for not less than 20 years but which may extend to imprisonment for life which shall mean imprisonment for the remainder of that person''s natural life and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "70(2)", "offence": "Gang rape on a woman under eighteen years of age.", "punishment": "Imprisonment for life which shall mean imprisonment for the remainder of that person''s natural life and with fine or with death.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('71', 71, 'Punishment for repeat offenders.', 'in_force', '[{"ref": "71", "offence": "Repeat offenders.", "punishment": "Imprisonment for life which shall mean imprisonment for the remainder of that person''s natural life or with death.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('72', 72, 'Disclosure of identity of victim of certain offences, etc.', 'in_force', '[{"ref": "72(1)", "offence": "Disclosure of identity of the victim of certain offences, etc.", "punishment": "Imprisonment for 2 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('73', 73, 'Printing or publishing any matter relating to Court proceedings without permission.', 'in_force', '[{"ref": "73", "offence": "Printing or publication of a proceeding without prior permission of court.", "punishment": "Imprisonment for 2 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('74', 74, 'Assault or use of criminal force to woman with intent to outrage her modesty.', 'in_force', '[{"ref": "74", "offence": "Assault or use of criminal force to woman with intent to outrage her modesty.", "punishment": "Imprisonment for 1 year which may extend to 5 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}]'),
('75', 75, 'Sexual harassment.', 'in_force', '[{"ref": "75(2)", "offence": "Sexual harassment and punishment for sexual harassment specified in clause (i) or clause (ii) or clause (iii) of sub-section (1).", "punishment": "Rigorous imprisonment with 3 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "75(3)", "offence": "Sexual harassment and punishment for sexual harassment specified in clause (iv) of sub-section (1).", "punishment": "Imprisonment for 1 year, or fine, or both.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('76', 76, 'Assault or use of criminal force to woman with intent to disrobe.', 'in_force', '[{"ref": "76", "offence": "Assault or use of criminal force to woman with intent to disrobe.", "punishment": "Imprisonment for not less than 3 years but which may extend to 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('77', 77, 'Voyeurism.', 'in_force', '[{"ref": "77", "offence": "Voyeurism.", "punishment": "Imprisonment for not less than 1 year but which may extend to 3 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Court of Session"}, {"ref": "77 (contd.)", "offence": "Second or subsequent conviction.", "punishment": "Imprisonment for not less than 3 years but which may extend to 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('78', 78, 'Stalking.', 'in_force', '[{"ref": "78(2)", "offence": "Stalking.", "punishment": "Imprisonment up to 3 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "78(2) (contd.)", "offence": "Second or subsequent conviction.", "punishment": "Imprisonment up to 5 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}]'),
('79', 79, 'Word, gesture or act intended to insult modesty of a woman.', 'in_force', '[{"ref": "79", "offence": "Uttering any word or making any gesture intended to insult the modesty of a woman, etc.", "punishment": "Simple imprisonment for 3 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('80', 80, 'Dowry death.', 'in_force', '[{"ref": "80(2)", "offence": "Dowry death.", "punishment": "Imprisonment for not less than 7 years but which may extend to imprisonment for life.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('81', 81, 'Cohabitation caused by man deceitfully inducing belief of lawful marriage.', 'in_force', '[{"ref": "81", "offence": "A man by deceit causing a woman not lawfully married to him to believe, that she is lawfully married to him and to cohabit with him in that belief.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Non-cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('82', 82, 'Marrying again during lifetime of husband or wife.', 'in_force', '[{"ref": "82(1)", "offence": "Marrying again during the life time of a husband or wife.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "82(2)", "offence": "Same offence with concealment of the former marriage from the person with whom subsequent marriage is contracted.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('83', 83, 'Marriage ceremony fraudulently gone through without lawful marriage.', 'in_force', '[{"ref": "83", "offence": "A person with fraudulent intention going through the ceremony of being married, knowing that he is not thereby lawfully married.", "punishment": "Imprisonment up to 7 years and fine.", "cognizable": "Non-cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('84', 84, 'Enticing or taking away or detaining with criminal intent a married woman.', 'in_force', '[{"ref": "84", "offence": "Enticing or taking away or detaining with a criminal intent a married woman.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('85', 85, 'Husband or relative of husband of a woman subjecting her to cruelty.', 'in_force', '[{"ref": "85", "offence": "Punishment for subjecting a married woman to cruelty.", "punishment": "Imprisonment for 3 years and fine.", "cognizable": "Cognizable if information relating to the commission of the offence is given to an officer in charge of a police station by the person aggrieved by the offence or by any person related to her by blood, marriage or adoption or if there is no such relative, by any public servant belonging to such class or category as may be notified by the State Government in this behalf", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('86', 86, 'Cruelty defined.', 'in_force', NULL),
('87', 87, 'Kidnapping, abducting or inducing woman to compel her marriage, etc.', 'in_force', '[{"ref": "87", "offence": "Kidnapping, abducting or inducing woman to compel her marriage, etc.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('88', 88, 'Causing miscarriage.', 'in_force', '[{"ref": "88", "offence": "Causing miscarriage.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "88 (contd.)", "offence": "If the woman be quick with child.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('89', 89, 'Causing miscarriage without woman''s consent.', 'in_force', '[{"ref": "89", "offence": "Causing miscarriage without women''s consent.", "punishment": "Imprisonment for life, or imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('90', 90, 'Death caused by act done with intent to cause miscarriage.', 'in_force', '[{"ref": "90(1)", "offence": "Death caused by an act done with intent to cause miscarriage.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "90(2)", "offence": "If act done without women''s consent.", "punishment": "Imprisonment for life, or as above.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('91', 91, 'Act done with intent to prevent child being born alive or to cause to die after birth.', 'in_force', '[{"ref": "91", "offence": "Act done with intent to prevent a child being born alive, or to cause it to die after its birth.", "punishment": "Imprisonment for 10 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
