('93', 93, 'Exposure and abandonment of child under twelve years of age, by parent or person having care of it.', 'in_force', '[{"ref": "93", "offence": "Exposure of a child under 12 years of age by parent or person having care of it with intention of wholly abandoning it.", "punishment": "Imprisonment for 7 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('94', 94, 'Concealment of birth by secret disposal of dead body.', 'in_force', '[{"ref": "94", "offence": "Concealment of birth by secret disposal of dead body.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('95', 95, 'Hiring, employing or engaging a child to commit an offence.', 'in_force', '[{"ref": "95", "offence": "Hiring, employing or engaging a child to commit an offence.", "punishment": "Imprisonment for not less than 3 years but which may extend to 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "95 (contd.)", "offence": "If offence be committed.", "punishment": "Same as for the offence committed.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court by which offence committed is triable"}]'),
('96', 96, 'Procuration of child.', 'in_force', '[{"ref": "96", "offence": "Procuration of child.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('97', 97, 'Kidnapping or abducting child under ten years of age with intent to steal from its person.', 'in_force', '[{"ref": "97", "offence": "Kidnapping or abducting a child under ten years with intent to steal from its person.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('98', 98, 'Selling child for purposes of prostitution, etc.', 'in_force', '[{"ref": "98", "offence": "Selling child for purposes of prostitution, etc.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
