('104', 104, 'Punishment for murder by life-convict.', 'in_force', '[{"ref": "104", "offence": "Murder by life-convict.", "punishment": "Death or imprisonment for life, which shall mean the remainder of that person''s natural life.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('105', 105, 'Punishment for culpable homicide not amounting to murder.', 'in_force', '[{"ref": "105", "offence": "Culpable homicide not amounting to murder, if act by which the death is caused is done with intention of causing death, etc.", "punishment": "Imprisonment for life, or Imprisonment for not less than 5 years but which may extend to 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "105 (contd.)", "offence": "If act be done with knowledge that it is likely to cause death, but without any intention to cause death, etc.", "punishment": "Imprisonment for 10 years and with fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
