('107', 107, 'Abetment of suicide of child or person of unsound mind.', 'in_force', '[{"ref": "107", "offence": "Abetment of suicide of child or person of unsound mind, etc.", "punishment": "Death, or imprisonment for life, or imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('108', 108, 'Abetment of suicide.', 'in_force', '[{"ref": "108", "offence": "Abetment of suicide.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('109', 109, 'Attempt to murder.', 'in_force', '[{"ref": "109(1)", "offence": "Attempt to murder.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "109(1) (contd.)", "offence": "If such act causes hurt to any person.", "punishment": "Imprisonment for life, or as above.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "109(2)", "offence": "Attempt by life-convict to murder, if hurt is caused.", "punishment": "Death, or imprisonment for life which shall mean the remainder of that person''s natural life.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
