('111', 111, 'Organised crime.', 'in_force', '[{"ref": "111(2)(a)", "offence": "Organised crime resulting in death of any person.", "punishment": "Death or imprisonment for life and fine of not less than 10 lakh rupees.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "111(2)(b)", "offence": "In any other case.", "punishment": "Imprisonment for not less than 5 years but which may extend to imprisonment for life and fine of not less than 5 lakh rupees.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "111(3)", "offence": "Abetting, attempting, conspiring or knowingly facilitating the commission of organised crime.", "punishment": "Imprisonment for not less than 5 years but which may extend to imprisonment for life and fine of not less than 5 lakh rupees.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "111(4)", "offence": "Being a member of an organised crime syndicate.", "punishment": "Imprisonment for not less than 5 years but which may extend to imprisonment for life and fine of not less than 5 lakh rupees.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "111(5)", "offence": "Intentionally harbouring or concealing any person who committed offence of organised crime.", "punishment": "Imprisonment for not less than 3 years but which may extend to imprisonment for life and fine of not less than 5 lakh rupees.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "111(6)", "offence": "Possessing property derived, or obtained from the commission of organised crime.", "punishment": "Imprisonment for not less than 3 years but which may extend to imprisonment for life and fine of not less than 2 lakh rupees.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "111(7)", "offence": "Possessing property on behalf of a member of an organised crime syndicate.", "punishment": "Imprisonment for not less than 3 years but which may extend to imprisonment for 10 years and fine of not less than 1 lakh rupees.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('112', 112, 'Petty organised crime.', 'in_force', '[{"ref": "112", "offence": "Petty Organised crime.", "punishment": "Imprisonment for not less than 1 year but which may extend to 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('113', 113, 'Terrorist act.', 'in_force', '[{"ref": "113(2)(a)", "offence": "Terrorist act resulting in the death of any person.", "punishment": "Death or imprisonment for life and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "113(2)(b)", "offence": "In any other case.", "punishment": "Imprisonment for not less than 5 years but which may extend to imprisonment for life and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "113(3)", "offence": "Conspiring, attempting, abetting, etc., or knowingly facilitating the commission of terrorist act.", "punishment": "Imprisonment for not less than 5 years but which may extend to imprisonment for life and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "113(4)", "offence": "Organising camps, training, etc., for commission of terrorist act.", "punishment": "Imprisonment for not less than 5 years but which may extend to imprisonment for life and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "113(5)", "offence": "Being a member of an organisation involved in terrorist act.", "punishment": "Imprisonment for life and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "113(6)", "offence": "Harbouring, concealing, etc., of any person who committed a terrorist act.", "punishment": "Imprisonment for not less than 3 years but which may extend to imprisonment for life and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "113(7)", "offence": "Possessing property derived or obtained from commission of terrorist act.", "punishment": "Imprisonment for life and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('114', 114, 'Hurt.', 'in_force', NULL),
