('120', 120, 'Voluntarily causing hurt or grievous hurt to extort confession, or to compel restoration of property.', 'in_force', '[{"ref": "120(1)", "offence": "Voluntarily causing hurt to extort confession or information, or to compel restoration of property, etc.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "120(2)", "offence": "Voluntarily causing grievous hurt to extort confession or information, or to compel restoration of property, etc.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
