('122', 122, 'Voluntarily causing hurt or grievous hurt on provocation.', 'in_force', '[{"ref": "122(1)", "offence": "Voluntarily causing hurt on grave and sudden provocation, not intending to hurt any other than the person who gave the provocation.", "punishment": "Imprisonment for 1 month, or fine of 5,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "122(2)", "offence": "Causing grievous hurt on grave and sudden provocation, not intending to hurt any other than the person who gave the provocation.", "punishment": "Imprisonment for 5 years, or fine of 10,000 rupees, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
