('187', 187, 'Person employed in mint causing coin to be of different weight or composition from that fixed by law.', 'in_force', '[{"ref": "187", "offence": "Person employed in a Mint causing coin to be of a different weight or composition from that fixed by law.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('188', 188, 'Unlawfully taking coining instrument from mint.', 'in_force', '[{"ref": "188", "offence": "Unlawfully taking from a Mint any coining instrument.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('189', 189, 'Unlawful assembly.', 'in_force', '[{"ref": "189(2)", "offence": "Being member of an unlawful assembly.", "punishment": "Imprisonment for 6 months, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "189(3)", "offence": "Joining or continuing in an unlawful assembly, knowing that it has been commanded to disperse.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "189(4)", "offence": "Joining an unlawful assembly armed with any deadly weapon.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "189(5)", "offence": "Knowingly joining or continuing in any assembly of five or more persons after it has been commanded to disperse.", "punishment": "Imprisonment for 6 months, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "189(6)", "offence": "Hiring, engaging or employing persons to take part in an unlawful assembly.", "punishment": "The same as for a member of such assembly, and for any offence committed by any member of such assembly.", "cognizable": "Cognizable", "bailable": "According as offence is bailable or non-bailable", "triableBy": "The Court by which the offence is triable"}, {"ref": "189(7)", "offence": "Harbouring persons hired for an unlawful assembly.", "punishment": "Imprisonment for 6 months, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "189(8)", "offence": "Being hired to take part in an unlawful assembly or riot.", "punishment": "Imprisonment for 6 months, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "189(9)", "offence": "Or to go armed.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('190', 190, 'Every member of unlawful assembly guilty of offence committed in prosecution of common object.', 'in_force', '[{"ref": "190", "offence": "Every member of unlawful assembly guilty of offence committed in prosecution of common object.", "punishment": "The same as for the offence.", "cognizable": "According as offence is cognizable or non-cognizable", "bailable": "According as offence is bailable or non-bailable", "triableBy": "The Court by which the offence is triable"}]'),
('191', 191, 'Rioting.', 'in_force', '[{"ref": "191(2)", "offence": "Rioting.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "191(3)", "offence": "Rioting, armed with a deadly weapon.", "punishment": "Imprisonment for 5 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('192', 192, 'Wantonly giving provocation with intent to cause riot-if rioting be committed; if not committed.', 'in_force', '[{"ref": "192", "offence": "Wantonly giving provocation with intent to cause riot, if rioting be committed.", "punishment": "Imprisonment for 1 year, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "192 (contd.)", "offence": "If not committed.", "punishment": "Imprisonment for 6 months, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('193', 193, 'Liability of owner, occupier, etc., of land on which an unlawful assembly or riot takes place.', 'in_force', '[{"ref": "193(1)", "offence": "Owner or occupier of land not giving information of riot, etc.", "punishment": "Fine of 1,000 rupees.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "193(2)", "offence": "Person for whose benefit or on whose behalf a riot takes place not using all lawful means to prevent it.", "punishment": "Fine.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "193(3)", "offence": "Agent of owner or occupier for whose benefit a riot is committed not using all lawful means to prevent it.", "punishment": "Fine.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('194', 194, 'Affray.', 'in_force', '[{"ref": "194(2)", "offence": "Committing affray.", "punishment": "Imprisonment for one month, or fine of 1,000 rupees, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('195', 195, 'Assaulting or obstructing public servant when suppressing riot, etc.', 'in_force', '[{"ref": "195(1)", "offence": "Assaulting or obstructing public servant when suppressing riot, etc.", "punishment": "Imprisonment for 3 years, or fine not less than 25,000 rupees, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "195(2)", "offence": "Threatening to assault or attempting to obstruct public servant when suppressing riot, etc.", "punishment": "Imprisonment for 1 year, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('196', 196, 'Promoting enmity between different groups on grounds of religion, race, place of birth, residence, language, etc., and doing acts prejudicial to maintenance of harmony.', 'in_force', '[{"ref": "196(1)", "offence": "Promoting enmity between different groups on ground of religion, race, place of birth, residence, language, etc., and doing acts prejudicial to maintenance of harmony.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "196(2)", "offence": "Promoting enmity between classes in place of worship, etc.", "punishment": "Imprisonment for 5 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('197', 197, 'Imputations, assertions prejudicial to national integration.', 'in_force', '[{"ref": "197(1)", "offence": "Imputations, assertions prejudicial to national integration.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "197(2)", "offence": "If committed in a place of public worship, etc.", "punishment": "Imprisonment for 5 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('198', 198, 'Public servant disobeying law, with intent to cause injury to any person.', 'in_force', '[{"ref": "198", "offence": "Public servant disobeying direction of the law with intent to cause injury to any person.", "punishment": "Simple imprisonment for 1 year, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('199', 199, 'Public servant disobeying direction under law.', 'in_force', '[{"ref": "199", "offence": "Public servant disobeying direction under law.", "punishment": "Rigorous imprisonment for not less than 6 months which may extend to 2 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('200', 200, 'Punishment for non-treatment of victim.', 'in_force', '[{"ref": "200", "offence": "Non-treatment of victim by hospital.", "punishment": "Imprisonment for 1 year, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('201', 201, 'Public servant framing an incorrect document with intent to cause injury.', 'in_force', '[{"ref": "201", "offence": "Public servant framing an incorrect document with intent to cause injury.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('202', 202, 'Public servant unlawfully engaging in trade.', 'in_force', '[{"ref": "202", "offence": "Public servant unlawfully engaging in trade.", "punishment": "Simple imprisonment for 1 year, or fine, or both, or community service.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('203', 203, 'Public servant unlawfully buying or bidding for property.', 'in_force', '[{"ref": "203", "offence": "Public servant unlawfully buying or bidding for property.", "punishment": "Simple imprisonment for 2 years, or fine, or both and confiscation of property, if purchased.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('204', 204, 'Personating a public servant.', 'in_force', '[{"ref": "204", "offence": "Personating a public servant.", "punishment": "Imprisonment for not less than 6 months but which may extend to 3 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}]'),
('205', 205, 'Wearing garb or carrying token used by public servant with fraudulent intent.', 'in_force', '[{"ref": "205", "offence": "Wearing garb or carrying token used by public servant with fraudulent intent.", "punishment": "Imprisonment for 3 months, or fine of 5,000 rupees, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('206', 206, 'Absconding to avoid service of summons or other proceeding.', 'in_force', '[{"ref": "206(a)", "offence": "Absconding to avoid service of summons or other proceeding from a public servant.", "punishment": "Simple imprisonment for 1 month, or fine of 5,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "206(b)", "offence": "If summons or notice require attendance in person, etc., in a Court.", "punishment": "Simple imprisonment for 6 months, or fine of 10,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('207', 207, 'Preventing service of summons or other proceeding, or preventing publication thereof.', 'in_force', '[{"ref": "207(a)", "offence": "Preventing service of summons or other proceeding, or preventing publication thereof.", "punishment": "Simple imprisonment for 1 month, or fine of 5,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "207(b)", "offence": "If summons, etc., require attendance in person, etc., in a Court.", "punishment": "Simple imprisonment for 6 months, or fine of 10,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('208', 208, 'Non-attendance in obedience to an order from public servant.', 'in_force', '[{"ref": "208(a)", "offence": "Non-attendance in obedience to an order from public servant.", "punishment": "Simple imprisonment for 1 month, or fine of 5,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "208(b)", "offence": "If the order requires personal attendance, etc., in a Court.", "punishment": "Simple imprisonment for 6 months, or fine of 10,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('209', 209, 'Non-appearance in response to a proclamation under section 84 of Bharatiya Nagarik Suraksha Sanhita, 2023.', 'in_force', '[{"ref": "209", "offence": "Non-appearance in response to a proclamation under section 84 of this Sanhita.", "punishment": "Imprisonment for 3 years, or fine, or both, or community service.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "209 (contd.)", "offence": "In a case where declaration has been made under sub-section (4) of section 84 of this Sanhita pronouncing a person as proclaimed offender.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('210', 210, 'Omission to produce document or electronic record to public servant by person legally bound to produce it', 'in_force', '[{"ref": "210(a)", "offence": "Omission to produce document to public servant by person legally bound to produce or deliver it.", "punishment": "Simple imprisonment for 1 month, or fine of 5,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "The Court in which the offence is committed, subject to the provisions of Chapter XXVIII; or, if not committed, in a Court, any Magistrate"}, {"ref": "210(b)", "offence": "If the document is required to be produced in or delivered to a Court.", "punishment": "Simple imprisonment for 6 months, or fine of 10,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "The Court in which the offence is committed, subject to the provisions of Chapter XXVIII; or, if not committed, in a Court, any Magistrate"}]'),
('211', 211, 'Omission to give notice or information to public servant by person legally bound to give it.', 'in_force', '[{"ref": "211(a)", "offence": "Intentional omission to give notice or information to public servant by person legally bound to give it.", "punishment": "Simple imprisonment for 1 month, or fine of 5,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "211(b)", "offence": "If the notice or information required respects the commission of an offence, etc.", "punishment": "Simple imprisonment for 6 months, or fine of 10,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "211(c)", "offence": "If the notice or information is required by an order passed under sub-section (1) of section 394 of this Sanhita.", "punishment": "Imprisonment for 6 months, or fine of 1,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('212', 212, 'Furnishing false information.', 'in_force', '[{"ref": "212(a)", "offence": "Knowingly furnishing false information to public servant.", "punishment": "Simple imprisonment for 6 months, or fine of 5,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "212(b)", "offence": "If the information required respects the commission of an offence, etc.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('213', 213, 'Refusing oath or affirmation when duly required by public servant to make it.', 'in_force', '[{"ref": "213", "offence": "Refusing oath when duly required to take oath by a public servant.", "punishment": "Simple imprisonment for 6 months, or fine of 5,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "The Court in which the offence is committed, subject to the provisions of Chapter XXVIII; or, if not committed, in a Court, any Magistrate"}]'),
('214', 214, 'Refusing to answer public servant authorised to question.', 'in_force', '[{"ref": "214", "offence": "Being legally bound to state truth, and refusing to answer public servant authorised to question.", "punishment": "Simple imprisonment for 6 months, or fine of 5,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "The Court in which the offence is committed, subject to the provisions of Chapter XXVIII; or, if not committed, in a Court, any Magistrate"}]'),
('215', 215, 'Refusing to sign statement.', 'in_force', '[{"ref": "215", "offence": "Refusing to sign a statement made to a public servant when legally required to do so.", "punishment": "Simple imprisonment for 3 months, or fine of 3,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "The Court in which the offence is committed, subject to the provisions of Chapter XXVIII; or, if not committed, in a Court, any Magistrate"}]'),
('216', 216, 'False statement on oath or affirmation to public servant or person authorised to administer an oath or affirmation.', 'in_force', '[{"ref": "216", "offence": "Knowingly stating to a public servant on oath as true that which is false.", "punishment": "Imprisonment for 3 years and fine.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('217', 217, 'False information, with intent to cause public servant to use his lawful power to injury of another person.', 'in_force', '[{"ref": "217", "offence": "Giving false information to a public servant in order to cause him to use his lawful power to the injury or annoyance of any person.", "punishment": "Imprisonment for 1 year, or with fine of 10,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('218', 218, 'Resistance to taking of property by lawful authority of a public servant.', 'in_force', '[{"ref": "218", "offence": "Resistance to the taking of property by the lawful authority of a public servant.", "punishment": "Imprisonment for 6 months, or fine of 10,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('219', 219, 'Obstructing sale of property offered for sale by authority of public servant.', 'in_force', '[{"ref": "219", "offence": "Obstructing sale of property offered for sale by authority of a public servant.", "punishment": "Imprisonment for 1 month, or fine of 5,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('220', 220, 'Illegal purchase or bid for property offered for sale by authority of public servant.', 'in_force', '[{"ref": "220", "offence": "Illegal purchase or bid for property offered for sale by authority of public servant.", "punishment": "Imprisonment for 1 month, or fine of 200 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('221', 221, 'Obstructing public servant in discharge of public functions.', 'in_force', '[{"ref": "221", "offence": "Obstructing public servant in discharge of his public functions.", "punishment": "Imprisonment for 3 months, or fine of 2,500 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('222', 222, 'Omission to assist public servant when bound by law to give assistance.', 'in_force', '[{"ref": "222(a)", "offence": "Omission to assist public servant when bound by law to give such assistance.", "punishment": "Simple imprisonment for 1 month, or fine of 2,500 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "222(b)", "offence": "Wilfully neglecting to aid a public servant who demands aid in the execution of process, the prevention of offences, etc.", "punishment": "Simple imprisonment for 6 months, or fine of 5,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('223', 223, 'Disobedience to order duly promulgated by public servant.', 'in_force', '[{"ref": "223(a)", "offence": "Disobedience to an order lawfully promulgated by a public servant, if such disobedience causes obstruction, annoyance or injury to persons lawfully employed.", "punishment": "Simple imprisonment for 6 months, or fine of 2,500 rupees, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "223(b)", "offence": "If such disobedience causes danger to human life, health or safety, or causes or tends to cause a riot or affray.", "punishment": "Imprisonment for 1 year, or fine of 5,000 rupees, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('224', 224, 'Threat of injury to public servant.', 'in_force', '[{"ref": "224", "offence": "Threat of injury to public servant, etc.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('225', 225, 'Threat of injury to induce person to refrain from applying for protection to public servant.', 'in_force', '[{"ref": "225", "offence": "Threat of injury to induce person to refrain from applying for protection to public servant.", "punishment": "Imprisonment for 1 year, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('226', 226, 'Attempt to commit suicide to compel or restrain exercise of lawful power.', 'in_force', '[{"ref": "226", "offence": "Attempt to commit suicide to compel or restraint exercise of lawful power.", "punishment": "Imprisonment for 1 year, or fine, or both, or community service.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('227', 227, 'Giving false evidence.', 'in_force', NULL),
('228', 228, 'Fabricating false evidence.', 'in_force', NULL),
('229', 229, 'Punishment for false evidence.', 'in_force', '[{"ref": "229(1)", "offence": "Intentionally giving or fabricating false evidence in a judicial proceeding.", "punishment": "Imprisonment for 7 years and 10,000 rupees.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "229(2)", "offence": "Giving or fabricating false evidence in any other case.", "punishment": "Imprisonment for 3 years and 5,000 rupees.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('230', 230, 'Giving or fabricating false evidence with intent to procure conviction of capital offence.', 'in_force', '[{"ref": "230(1)", "offence": "Giving or fabricating false evidence with intent to cause any person to be convicted of capital offence.", "punishment": "Imprisonment for life, or rigorous imprisonment for 10 years and 50,000 rupees.", "cognizable": "Non-cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "230(2)", "offence": "If innocent person be thereby convicted and executed.", "punishment": "Death, or as above.", "cognizable": "Non-cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('231', 231, 'Giving or fabricating false evidence with intent to procure conviction of offence punishable with imprisonment for life or imprisonment.', 'in_force', '[{"ref": "231", "offence": "Giving or fabricating false evidence with intent to procure conviction of an offence punishable with imprisonment for life or with imprisonment for 7 years, or upwards.", "punishment": "The same as for the offence.", "cognizable": "Non-cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('232', 232, 'Threatening any person to give false evidence.', 'in_force', '[{"ref": "232(1)", "offence": "Threatening any person to give false evidence.", "punishment": "Imprisonment for 7 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court by which offence of giving false evidence is triable"}, {"ref": "232(2)", "offence": "If innocent person is convicted and sentenced in consequence of false evidence with death, or imprisonment for more than 7 years.", "punishment": "The same as for the offence.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court by which offence of giving false evidence is triable"}]'),
('233', 233, 'Using evidence known to be false.', 'in_force', '[{"ref": "233", "offence": "Using in a judicial proceeding evidence known to be false or fabricated.", "punishment": "The same as for giving or fabricating false evidence.", "cognizable": "Non-cognizable", "bailable": "According as offence of giving such evidence is bailable or non-bailable", "triableBy": "Court by which offence of giving or fabricating false evidence is triable"}]'),
('234', 234, 'Issuing or signing false certificate.', 'in_force', '[{"ref": "234", "offence": "Knowingly issuing or signing a false certificate relating to any fact of which such certificate is by law admissible in evidence.", "punishment": "The same as for giving false evidence.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Court by which offence of giving false evidence is triable"}]'),
('235', 235, 'Using as true a certificate known to be false.', 'in_force', '[{"ref": "235", "offence": "Using as a true certificate one known to be false in a material point.", "punishment": "The same as for giving false evidence.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Court by which offence of giving false evidence is triable"}]'),
('236', 236, 'False statement made in declaration which is by law receivable as evidence.', 'in_force', '[{"ref": "236", "offence": "False statement made in any declaration which is by law receivable as evidence.", "punishment": "The same as for giving false evidence.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Court by which offence of giving false evidence is triable"}]'),
('237', 237, 'Using as true such declaration knowing it to be false.', 'in_force', '[{"ref": "237", "offence": "Using as true any such declaration known to be false.", "punishment": "The same as for giving false evidence.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Court by which offence of giving false evidence is triable"}]'),
('238', 238, 'Causing disappearance of evidence of offence, or giving false information to screen offender.', 'in_force', '[{"ref": "238(a)", "offence": "Causing disappearance of evidence of an offence committed, or giving false information touching it to screen the offender, if a capital offence.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "According as the offence in relation to which disappearance of evidence is caused is cognizable or non-cognizable", "bailable": "Bailable", "triableBy": "Court of Session"}, {"ref": "238(b)", "offence": "If punishable with imprisonment for life or imprisonment for 10 years.", "punishment": "Imprisonment for 3 years and fine.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "238(c)", "offence": "If punishable with less than 10 years'' imprisonment.", "punishment": "Imprisonment for one-fourth of the longest term provided for the offence, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Court by which the offence is triable"}]'),
('239', 239, 'Intentional omission to give information of offence by person bound to inform.', 'in_force', '[{"ref": "239", "offence": "Intentional omission to give information of an offence by a person legally bound to inform.", "punishment": "Imprisonment for 6 months, or fine of 5,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('240', 240, 'Giving false information respecting an offence committed.', 'in_force', '[{"ref": "240", "offence": "Giving false information respecting an offence committed.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
