('242', 242, 'False personation for purpose of act or proceeding in suit or prosecution.', 'in_force', '[{"ref": "242", "offence": "False personation for the purpose of any act or proceeding in a suit or criminal prosecution, or for becoming bail or security.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
