('246', 246, 'Dishonestly making false claim in Court.', 'in_force', '[{"ref": "246", "offence": "False claim in a Court.", "punishment": "Imprisonment for 2 years and fine.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('247', 247, 'Fraudulently obtaining decree for sum not due.', 'in_force', '[{"ref": "247", "offence": "Fraudulently obtaining a decree for a sum not due, or causing a decree to be executed after it has been satisfied.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
