('249', 249, 'Harbouring offender.', 'in_force', '[{"ref": "249(a)", "offence": "Harbouring an offender, if the offence is punishable with death.", "punishment": "Imprisonment for 5 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "249(b)", "offence": "If punishable with imprisonment for life or with imprisonment for 10 years.", "punishment": "Imprisonment for 3 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "249(c)", "offence": "If punishable with imprisonment for 1 year and not for 10 years.", "punishment": "Imprisonment for one-fourth of the longest term, and of the descriptions, provided for the offence, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
