('252', 252, 'Taking gift to help to recover stolen property, etc.', 'in_force', '[{"ref": "252", "offence": "Taking gift to help to recover movable property of which a person has been deprived by an offence without causing apprehension of offender.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
