('258', 258, 'Commitment for trial or confinement by person having authority who knows that he is acting contrary to law', 'in_force', '[{"ref": "258", "offence": "Commitment for trial or confinement by a person having authority, who knows that he is acting contrary to law.", "punishment": "Imprisonment for 7 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
