('301', 301, 'Trespassing on burial places, etc.', 'in_force', '[{"ref": "301", "offence": "Trespassing on burial places, etc.", "punishment": "Imprisonment for 1 year, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('302', 302, 'Uttering words, etc., with deliberate intent to wound religious feelings of any person.', 'in_force', '[{"ref": "302", "offence": "Uttering words, etc., with deliberate intent to wound religious feelings.", "punishment": "Imprisonment for 1 year, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('303', 303, 'Theft.', 'in_force', '[{"ref": "303(2)", "offence": "Theft.", "punishment": "Rigorous imprisonment for not be less than 1 year but which may extend to 5 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}, {"ref": "303(2) (contd.)", "offence": "Where value of property is less than 5,000 rupees.", "punishment": "Upon return of the value of property or restoration of the stolen property, shall be punished with community service.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('304', 304, 'Snatching.', 'in_force', '[{"ref": "304(2)", "offence": "Snatching.", "punishment": "Imprisonment for 3 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}]'),
('305', 305, 'Theft in a dwelling house, or means of transportation or place of worship, etc.', 'in_force', '[{"ref": "305", "offence": "Theft in a dwelling house, or means of transportation or place of worship, etc.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}]'),
('306', 306, 'Theft by clerk or servant of property in possession of master.', 'in_force', '[{"ref": "306", "offence": "Theft by clerk or servant of property in possession of master or employer.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}]'),
('307', 307, 'Theft after preparation made for causing death, hurt or restraint in order to committing of theft.', 'in_force', '[{"ref": "307", "offence": "Theft after preparation made for causing death, hurt or restraint in order to the committing of theft.", "punishment": "Rigorous imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('308', 308, 'Extortion.', 'in_force', '[{"ref": "308(2)", "offence": "Extortion.", "punishment": "Imprisonment for 7 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "308(3)", "offence": "Putting or attempting to put in fear of injury, in order to commit extortion.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "308(4)", "offence": "Putting or attempting to put a person in fear of death or grievous hurt in order to commit extortion.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "308(5)", "offence": "Extortion by putting a person in fear of death or grievous hurt.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "308(6)", "offence": "Putting a person in fear of accusation of an offence punishable with death, imprisonment for life, or imprisonment for 10 years in order to commit extortion.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "308(7)", "offence": "Extortion by threat of accusation of an offence punishable with death, imprisonment for life, or imprisonment for 10 years.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('309', 309, 'Robbery.', 'in_force', '[{"ref": "309(4)", "offence": "Robbery.", "punishment": "Rigorous imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "309(4) (contd.)", "offence": "If robbery committed on highway between sunset and sunrise.", "punishment": "Rigorous imprisonment for 14 years.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "309(5)", "offence": "Attempt to commit robbery.", "punishment": "Rigorous imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "309(6)", "offence": "Causing hurt.", "punishment": "Imprisonment for life, or rigorous imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('310', 310, 'Dacoity.', 'in_force', '[{"ref": "310(2)", "offence": "Dacoity.", "punishment": "Imprisonment for life, or rigorous imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "310(3)", "offence": "Murder in dacoity.", "punishment": "Death, imprisonment for life, or rigorous imprisonment for not less than 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "310(4)", "offence": "Making preparation to commit dacoity.", "punishment": "Rigorous imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "310(5)", "offence": "Being one of five or more persons assembled for the purpose of committing dacoity.", "punishment": "Rigorous imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "310(6)", "offence": "Belonging to a gang of persons associated for the purpose of habitually committing dacoity.", "punishment": "Imprisonment for life, or rigorous imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('311', 311, 'Robbery, or dacoity, with attempt to cause death or grievous hurt.', 'in_force', '[{"ref": "311", "offence": "Robbery or dacoity, with attempt to cause death or grievous hurt.", "punishment": "Imprisonment for not less than 7 years.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('312', 312, 'Attempt to commit robbery or dacoity when armed with deadly weapon.', 'in_force', '[{"ref": "312", "offence": "Attempt to commit robbery or dacoity when armed with deadly weapon.", "punishment": "Imprisonment for not less than 7 years.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('313', 313, 'Punishment for belonging to gang of robbers, etc.', 'in_force', '[{"ref": "313", "offence": "Belonging to a wandering gang of persons associated for the purpose of habitually committing thefts.", "punishment": "Rigorous imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('314', 314, 'Dishonest misappropriation of property.', 'in_force', '[{"ref": "314", "offence": "Dishonest misappropriation of movable property, or converting it to one''s own use.", "punishment": "Imprisonment of not less than 6 months but which may extend to 2 years and fine.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('315', 315, 'Dishonest misappropriation of property possessed by deceased person at the time of his death.', 'in_force', '[{"ref": "315", "offence": "Dishonest misappropriation of property possessed by deceased person at the time of his death.", "punishment": "Imprisonment for 3 years and fine.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "315 (contd.)", "offence": "If by clerk or person employed by deceased.", "punishment": "Imprisonment for 7 years.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('316', 316, 'Criminal breach of trust.', 'in_force', '[{"ref": "316(2)", "offence": "Criminal breach of trust.", "punishment": "Imprisonment for 5 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "316(3)", "offence": "Criminal breach of trust by a carrier, wharfinger, etc.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "316(4)", "offence": "Criminal breach of trust by a clerk or servant.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "316(5)", "offence": "Criminal breach of trust by public servant or by banker, merchant or agent, etc.", "punishment": "Imprisonment for life, or imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('317', 317, 'Stolen property.', 'in_force', '[{"ref": "317(2)", "offence": "Dishonestly receiving stolen property knowing it to be stolen.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}, {"ref": "317(3)", "offence": "Dishonestly receiving stolen property, knowing that it was obtained by dacoity.", "punishment": "Imprisonment for life, or rigorous imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "317(4)", "offence": "Habitually dealing in stolen property.", "punishment": "Imprisonment for life, or imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "317(5)", "offence": "Assisting in concealment or disposal of stolen property, knowing it to be stolen.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}]'),
('318', 318, 'Cheating.', 'in_force', '[{"ref": "318(2)", "offence": "Cheating.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "318(3)", "offence": "Cheating a person whose interest the offender was bound, either by law or by legal contract, to protect.", "punishment": "Imprisonment for 5 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "318(4)", "offence": "Cheating and dishonestly inducing delivery of property.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('319', 319, 'Cheating by personation.', 'in_force', '[{"ref": "319(2)", "offence": "Cheating by personation.", "punishment": "Imprisonment for 5 years, or with fine, or with both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('320', 320, 'Dishonest or fraudulent removal or concealment of property to prevent distribution among creditors.', 'in_force', '[{"ref": "320", "offence": "Fraudulent removal or concealment of property, etc., to prevent distribution among creditors.", "punishment": "Imprisonment of not be less than 6 months but which may extend to 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('321', 321, 'Dishonestly or fraudulently preventing debt being available for creditors.', 'in_force', '[{"ref": "321", "offence": "Dishonest or fraudulently preventing from being made available for his creditors a debt or demand due to the offender.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('322', 322, 'Dishonest or fraudulent execution of deed of transfer containing false statement of consideration.', 'in_force', '[{"ref": "322", "offence": "Dishonest or fraudulent execution of deed of transfer containing a false statement of consideration.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('323', 323, 'Dishonest or fraudulent removal or concealment of property.', 'in_force', '[{"ref": "323", "offence": "Fraudulent removal or concealment of property, of himself or any other person or assisting in the doing thereof, or dishonestly releasing any demand or claim to which he is entitled.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('324', 324, 'Mischief.', 'in_force', '[{"ref": "324(2)", "offence": "Mischief.", "punishment": "Imprisonment for 6 months, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "324(3)", "offence": "Mischief causing loss or damage to any property including property of Government or Local Authority.", "punishment": "Imprisonment for 1 year, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "324(4)", "offence": "Mischief causing loss or damage to the amount of twenty thousand rupees but less than 2 lakh rupees.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "324(5)", "offence": "Mischief causing loss or damage to the amount of one lakh rupees or upwards.", "punishment": "Imprisonment for 5 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "324(6)", "offence": "Mischief with preparation for causing to any person death, or hurt, or wrongful restraint, or fear of death, or of hurt, or of wrongful restraint.", "punishment": "Imprisonment for 5 years, and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('325', 325, 'Mischief by killing or maiming animal.', 'in_force', '[{"ref": "325", "offence": "Mischief by killing or maiming animal.", "punishment": "Imprisonment for 5 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('326', 326, 'Mischief by injury, inundation, fire or explosive substance, etc.', 'in_force', '[{"ref": "326(a)", "offence": "Mischief by causing diminution of supply of water for agricultural purposes, etc.", "punishment": "Imprisonment for 5 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "326(b)", "offence": "Mischief by injury to public road, bridge, navigable river, or navigable channel, and rendering it impassable or less safe for travelling or conveying property.", "punishment": "Imprisonment for 5 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "326(c)", "offence": "Mischief by causing inundation or obstruction to public drainage attended with damage.", "punishment": "Imprisonment for 5 years, or with fine, or with both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "326(d)", "offence": "Mischief by destroying or moving or rendering less useful a lighthouse or seamark, or by exhibiting false lights.", "punishment": "Imprisonment for 7 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "326(e)", "offence": "Mischief by destroying or moving, etc., a landmark fixed by public authority.", "punishment": "Imprisonment for 1 year, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "326(f)", "offence": "Mischief by fire or explosive substance with intent to cause damage.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "326(g)", "offence": "Mischief by fire or explosive substance with intent to destroy a house, etc.", "punishment": "Imprisonment for life, or imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('327', 327, 'Mischief with intent to destroy or make unsafe a rail, aircraft, decked vessel or one of twenty tons burden.', 'in_force', '[{"ref": "327(1)", "offence": "Mischief with intent to destroy or make unsafe a decked vessel or a vessel of 20 tonnes burden.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "327(2)", "offence": "The mischief described in the last section when committed by fire or any explosive substance.", "punishment": "Imprisonment for life, or imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('328', 328, 'Punishment for intentionally running vessel aground or ashore with intent to commit theft, etc.', 'in_force', '[{"ref": "328", "offence": "Running vessel with intent to commit theft, etc.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('329', 329, 'Criminal trespass and house-trespass.', 'in_force', '[{"ref": "329(3)", "offence": "Criminal trespass.", "punishment": "Imprisonment for 3 months, or fine of 5,000 rupees, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "329(4)", "offence": "House-trespass.", "punishment": "Imprisonment for 1 year, or fine of 5,000 rupees, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('330', 330, 'House-trespass and hous-ebreaking.', 'in_force', NULL),
('331', 331, 'Punishment for house-trespass or house-breaking.', 'in_force', '[{"ref": "331(1)", "offence": "Lurking house-trespass or house-breaking.", "punishment": "Imprisonment for 2 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}, {"ref": "331(2)", "offence": "Lurking house-trespass or house-breaking by night.", "punishment": "Imprisonment for 3 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}, {"ref": "331(3)", "offence": "Lurking house-trespass or house-breaking in order to the commission of an offence punishable with imprisonment.", "punishment": "Imprisonment for 3 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}, {"ref": "331(3) (contd.)", "offence": "If the offence be theft.", "punishment": "Imprisonment for 10 years.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "331(4)", "offence": "Lurking house-trespass or house-breaking by night in order to the commission of an offence punishable with imprisonment.", "punishment": "Imprisonment for 5 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}, {"ref": "331(4) (contd.)", "offence": "If the offence be theft.", "punishment": "Imprisonment for 14 years.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "331(5)", "offence": "Lurking house-trespass or house-breaking after preparation made for causing hurt, assault, etc.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "331(6)", "offence": "Lurking house-trespass or house-breaking by night, after preparation made for causing hurt, etc.", "punishment": "Imprisonment for 14 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "331(7)", "offence": "Grievous hurt caused whilst committing lurking house-trespass or house-breaking.", "punishment": "Imprisonment for life, or imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "331(8)", "offence": "Death or grievous hurt caused by one of several persons jointly concerned in house-breaking by night, etc.", "punishment": "Imprisonment for life, or imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}]'),
('332', 332, 'House-trespass in order to commit offence.', 'in_force', '[{"ref": "332(a)", "offence": "House-trespass in order to the commission of an offence punishable with death.", "punishment": "Imprisonment for life, or rigorous imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "332(b)", "offence": "House-trespass in order to the commission of an offence punishable with imprisonment for life.", "punishment": "Imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Court of Session"}, {"ref": "332(c)", "offence": "House-trespass in order to the commission of an offence punishable with imprisonment.", "punishment": "Imprisonment for 2 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "332(c) (contd.)", "offence": "If the offence is theft.", "punishment": "Imprisonment for 7 years.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}]'),
('333', 333, 'House-trespass after preparation for hurt, assault or wrongful restraint.', 'in_force', '[{"ref": "333", "offence": "House-trespass, having made preparation for causing hurt, assault, etc.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}]'),
('334', 334, 'Dishonestly breaking open receptacle containing property.', 'in_force', '[{"ref": "334(1)", "offence": "Dishonestly breaking open or unfastening any closed receptacle containing or supposed to contain property.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}, {"ref": "334(2)", "offence": "Being entrusted with any closed receptacle containing or supposed to contain any property, and fraudulently opening the same.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('335', 335, 'Making a false document.', 'in_force', NULL),
('336', 336, 'Forgery.', 'in_force', '[{"ref": "336(2)", "offence": "Forgery.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "336(3)", "offence": "Forgery for the purpose of cheating.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "336(4)", "offence": "Forgery for the purpose of harming the reputation of any person or knowing that it is likely to be used for that purpose.", "punishment": "Imprisonment for 3 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('337', 337, 'Forgery of record of Court or of public register, etc.', 'in_force', '[{"ref": "337", "offence": "Forgery of a record of a Court or of a Registrar of Births, etc., kept by a public servant.", "punishment": "Imprisonment for 7 years and fine", "cognizable": "Non-cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('338', 338, 'Forgery of valuable security, will, etc.', 'in_force', '[{"ref": "338", "offence": "Forgery of a valuable security, will, or authority to make or transfer any valuable security, or to receive any money, etc.", "punishment": "Imprisonment for life, or imprisonment for 10 years and fine.", "cognizable": "Non-cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}, {"ref": "338 (contd.)", "offence": "When the valuable security is a promissory note of the Central Government.", "punishment": "Imprisonment for life, or imprisonment for 10 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('339', 339, 'Having possession of document described in section 337 or section 338, knowing it to be forged and intending to use it as genuine.', 'in_force', '[{"ref": "339", "offence": "Having possession of a document, knowing it to be forged, with intent to use it as genuine; if the document is one of the description mentioned in section 337.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "339 (contd.)", "offence": "If the document is one of the description mentioned in section 338.", "punishment": "Imprisonment for life, or imprisonment for 7 years and fine.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('340', 340, 'Forged document or electronic record and using it as genuine.', 'in_force', '[{"ref": "340(2)", "offence": "Using as genuine a forged document which is known to be forged.", "punishment": "Punishment for forgery of such document.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('341', 341, 'Making or possessing counterfeit seal, etc., with intent to commit forgery punishable under section 338.', 'in_force', '[{"ref": "341(1)", "offence": "Making or counterfeiting a seal, plate, etc., with intent to commit a forgery punishable under section 338 or possessing with like intent any such seal, plate, etc., knowing the same to be counterfeit.", "punishment": "Imprisonment for life, or imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "341(2)", "offence": "Making or counterfeiting a seal, plate, etc., with intent to commit a forgery punishable otherwise than under section 338 or possessing with like intent any such seal, plate, etc., knowing the same to be counterfeit.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "341(3)", "offence": "Possesses any seal, plate or other instrument knowing the same to be counterfeit.", "punishment": "Imprisonment for 3 years and fine.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "341(4)", "offence": "Fraudulently or dishonestly uses as genuine any seal, plate or other instrument knowing or having reason to believe the same to be counterfeit.", "punishment": "Same as if he had made or counterfeited such seal, plate or other instrument.", "cognizable": "Cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('342', 342, 'Counterfeiting device or mark used for authenticating documents described in section 338, or possessing counterfeit marked material.', 'in_force', '[{"ref": "342(1)", "offence": "Counterfeiting a device or mark used for authenticating documents described in section 338 or possessing counterfeit marked material.", "punishment": "Imprisonment for life, or imprisonment for 7 years and fine.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "342(2)", "offence": "Counterfeiting a device or mark used for authenticating documents other than those described in section 338 or possessing counterfeit marked material.", "punishment": "Imprisonment for 7 years and fine.", "cognizable": "Non-cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('343', 343, 'Fraudulent cancellation, destruction, etc., of will, authority to adopt, or valuable security.', 'in_force', '[{"ref": "343", "offence": "Fraudulently destroying or defacing, or attempting to destroy or deface, or secreting, a will, etc.", "punishment": "Imprisonment for life, or imprisonment for 7 years and fine.", "cognizable": "Non-cognizable", "bailable": "Non-bailable", "triableBy": "Magistrate of the first class"}]'),
('344', 344, 'Falsification of accounts.', 'in_force', '[{"ref": "344", "offence": "Falsification of accounts.", "punishment": "Imprisonment for 7 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('345', 345, 'Property mark.', 'in_force', '[{"ref": "345(3)", "offence": "Using a false property mark with intent to deceive or injure any person.", "punishment": "Imprisonment for 1 year, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('346', 346, 'Tampering with property mark with intent to cause injury.', 'in_force', '[{"ref": "346", "offence": "Removing, destroying or defacing property mark with intent to cause injury.", "punishment": "Imprisonment for 1 year, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('347', 347, 'Counterfeiting a property mark.', 'in_force', '[{"ref": "347(1)", "offence": "Counterfeiting a property mark used by another, with intent to cause damage or injury.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "347(2)", "offence": "Counterfeiting a property mark used by a public servant, or any mark used by him to denote the manufacture, quality, etc., of any property.", "punishment": "Imprisonment for 3 years and fine.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('348', 348, 'Making or possession of any instrument for counterfeiting a property mark.', 'in_force', '[{"ref": "348", "offence": "Fraudulently making or having possession of any die, plate or other instrument for counterfeiting any public or private property mark.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('349', 349, 'Selling goods marked with a counterfeit property mark.', 'in_force', '[{"ref": "349", "offence": "Knowingly selling goods marked with a counterfeit property mark.", "punishment": "Imprisonment for 1 year, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('350', 350, 'Making a false mark upon any receptacle containing goods.', 'in_force', '[{"ref": "350(1)", "offence": "Fraudulently making a false mark upon any package or receptacle containing goods, with intent to cause it to be believed that it contains goods, which it does not contain, etc.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "350(2)", "offence": "Making use of any such false mark.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('351', 351, 'Criminal intimidation.', 'in_force', '[{"ref": "351(2)", "offence": "Criminal intimidation.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}, {"ref": "351(3)", "offence": "If threat be to cause death or grievous hurt, etc.", "punishment": "Imprisonment for 7 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "351(4)", "offence": "Criminal intimidation by anonymous communication or having taken precaution to conceal whence the threat comes.", "punishment": "Imprisonment for 2 years, in addition to the punishment under section 351(1).", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('352', 352, 'Intentional insult with intent to provoke breach of peace.', 'in_force', '[{"ref": "352", "offence": "Insult intended to provoke breach of the peace.", "punishment": "Imprisonment for 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('353', 353, 'Statements conducing to public mischief.', 'in_force', '[{"ref": "353(1)", "offence": "False statement, rumour, etc., circulated with intent to cause mutiny or offence against the public peace.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}, {"ref": "353(2)", "offence": "False statement, rumour, etc., with intent to create enmity, hatred or ill-will between different classes.", "punishment": "Imprisonment for 3 years, or fine, or both.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}, {"ref": "353(3)", "offence": "False statement, rumour, etc., made in place of worship, etc., with intent to create enmity, hatred or ill-will.", "punishment": "Imprisonment for 5 years and fine.", "cognizable": "Cognizable", "bailable": "Non-bailable", "triableBy": "Any Magistrate"}]'),
('354', 354, 'Act caused by inducing person to believe that he will be rendered an object of Divine displeasure.', 'in_force', '[{"ref": "354", "offence": "Act caused by inducing a person to believe that he will be rendered an object of Divine displeasure.", "punishment": "Imprisonment for 1 year, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('355', 355, 'Misconduct in public by a drunken person.', 'in_force', '[{"ref": "355", "offence": "Appearing in a public place, etc., in a state of intoxication, and causing annoyance to any person.", "punishment": "Simple imprisonment for 24 hours, or fine of 1,000 rupees, or both or with community service.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('356', 356, 'Defamation.', 'in_force', '[{"ref": "356(2)", "offence": "Defamation against the President or the Vice-President or the Governor of a State or Administrator of a Union territory or a Minister in respect of his conduct in the discharge of his public functions when instituted upon a complaint made by the Public Prosecutor.", "punishment": "Simple imprisonment for 2 years, or fine or both, or community service.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Court of Session"}, {"ref": "356(2) (contd.)", "offence": "Defamation in any other case.", "punishment": "Simple imprisonment for 2 years, or fine or both, or community service.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "356(3)", "offence": "Printing or engraving matter knowing it to be defamatory against the President or the Vice-President or the Governor of a State or Administrator of a Union territory or a Minister in respect of his conduct in the discharge of his public functions when instituted upon a complaint made by the Public Prosecutor.", "punishment": "Simple imprisonment for 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Court of Session"}, {"ref": "356(3) (contd.)", "offence": "Printing or engraving matter knowing it to be defamatory, in any other case.", "punishment": "Simple imprisonment for 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}, {"ref": "356(4)", "offence": "Sale of printed or engraved substance containing defamatory matter, knowing it to contain such matter against the President or the Vice-President or the Governor of a State or Administrator of a Union territory or a Minister in respect of his conduct in the discharge of his public functions when instituted upon a complaint made by the Public Prosecutor.", "punishment": "Simple imprisonment for 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Court of Session"}, {"ref": "356(4) (contd.)", "offence": "Sale of printed or engraved substance containing defamatory matter, knowing it to contain such matter in any other case.", "punishment": "Simple imprisonment for 2 years, or fine, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Magistrate of the first class"}]'),
('357', 357, 'Breach of contract to attend on and supply wants of helpless person.', 'in_force', '[{"ref": "357", "offence": "Being bound to attend on or supply the wants of a person who is helpless from youth, unsoundness of mind or disease, and voluntarily omitting to do so.", "punishment": "Imprisonment for 3 months, or fine of 5,000 rupees, or both.", "cognizable": "Non-cognizable", "bailable": "Bailable", "triableBy": "Any Magistrate"}]'),
('358', 358, 'Repeal and savings.', 'in_force', NULL)
) AS v(number, sort_order, heading, status, classification)
WHERE a.code = 'BNS'
ON CONFLICT (act_id, number) DO NOTHING;

